/bin/zsh -lc "cat validation/rc10/candidate-runtime/learning-time-bound-inspection.json; python3 - <<'PY'
import json,pathlib,subprocess,datetime
p=pathlib.Path('validation/rc10/candidate-runtime');base=['multica','--workspace-id','0b02adb6-a395-46bd-bd92-6fec14dee20e']
for name,args in [('parent',['issue','get','01a0dda7-01b9-76f7-b53b-e2e629a042c2']),('parent-active',['issue','runs','01a0dda7-01b9-76f7-b53b-e2e629a042c2','--active']),('parent-comments',['issue','comment','list','01a0dda7-01b9-76f7-b53b-e2e629a042c2','--since','2026-09-26T12:54:00Z']),('c1-comments',['issue','comment','list','01a0ddac-eb7a-7288-849a-eb75fb015eb0','--since','2026-09-26T12:54:00Z'])]:
 r=subprocess.run(base+args+['--output','json'],capture_output=True);(p/('learning-continuation-'+name+'.json')).write_bytes(r.stdout);assert r.returncode==0
 x=json.loads(r.stdout)
 if name=='parent':print('metadata',json.dumps(x.get('metadata')))
 elif 'comments' in name:
  for c in x:print(json.dumps({k:c.get(k) for k in ['id','author_id','source_task_id','content']},ensure_ascii=False))
 else:print(name,[{k:z.get(k) for k in ['id','agent_id','status']} for z in x])
PY"

